# REDACTED DERIVATIVE, generated by paper/make_release_tree.py.
# The private canonical file is NOT released and was NOT modified.
# Speaker names are pseudonymised; private roots are masked to
# <PRIVATE_SOURCE_ROOT> etc. Set them locally to re-run.
# Source sha256: 9360a7a7e4f2d2b118020c50fab3e4048c6e4e7481e57ab20dcce1fdd9d12ffd
r"""M3 — THE RETROSPECTIVE STAGE 1 DETERMINISM CHECK.

⛔ WHAT THE §7.2 GATE DID NOT PROVE. `gate4_determinism.py` ran AFTER Stage 2,
and it compared two FRESH decodes to EACH OTHER. That shows an arm is a function
of its input TODAY, in THIS process. It does NOT show that the waveforms Stage 1
persisted - the bytes every `mcd` value was computed from - are what the frozen
path produces now. A drift between the Stage 1 session and today (driver, load
order, library version, non-deterministic kernel selection) would be invisible to
a self-vs-self probe and would invalidate the measurements without failing it.

THIS CLOSES THAT GAP THE ONLY WAY IT CAN BE CLOSED: re-decode a representative
sample of the ACTUAL Stage 1 cells and compare the **SHA-256 of the re-decoded
waveform against the hash recorded in the Stage 1 manifest**, byte for byte.

Sampling is DECLARED AND DETERMINISTIC: `N_PER_ARM` cells per arm, drawn by a
fixed-seed permutation of that arm's OK cells, stratified so every state present
is represented before any state repeats. No cell is chosen by its result.

    <decbench>/python.exe gate4_retro_sha.py --env decbench
    <fish>/python.exe     gate4_retro_sha.py --env fish

⛔ ONE GPU PROCESS AT A TIME (§7.4). ⛔ WRITES NO WAVEFORM into the study tree -
re-decodes are hashed in memory and discarded, so no Stage 1 output is touched.
"""
import argparse
import hashlib
import io
import json
import os
import sys
import time
import traceback

import numpy as np
import soundfile as sf
import torch

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import gate4_lib as G4          # noqa: E402  frozen: the one resampler
import gate4_run as R1          # noqa: E402  frozen: the Stage 1 decode path

N_PER_ARM = 12
SAMPLE_SEED = 20260913          # declared here, before the run

MATCH = "SHA-256 MATCH"
MISMATCH = "STAGE 1 REPRODUCTION FAILED - SHA-256 MISMATCH"


def sha256_bytes(b):
    h = hashlib.sha256()
    h.update(b)
    return h.hexdigest()


def data_sha256(x):
    """SHA-256 of the SAMPLES, little-endian float32 - the exact dtype Stage 1
    persisted. Container-independent and therefore reproducible.

    ⛔ WHY NOT THE FILE HASH. MEASURED here, and it is the reason this module
    exists in its present form: **a WAV file written by libsndfile is not
    reproducible byte-for-byte.** Rewriting a persisted Stage 1 waveform from
    its own samples yields a file of identical length differing in exactly
    THREE bytes, at offsets 60-62 - inside the `PEAK` chunk, which carries a
    CREATION TIMESTAMP. The first version of this check compared file hashes and
    reported 0/12 MATCH for dac44 while every sample was bit-identical
    (max_abs_diff 0.0, length_delta 0). That was an artefact of the comparison.
    **The Stage 1 SHA-256 is therefore a FILE-INTEGRITY hash - it proves the
    waveform on disk is the one Stage 2 measured - and it can NEVER serve as a
    decode-reproducibility check.** Both are verified below, separately.
    """
    return sha256_bytes(np.asarray(x, dtype="<f4").reshape(-1).tobytes())


def sample_cells(rows, n, seed=SAMPLE_SEED):
    """Deterministic, stratified over states, chosen WITHOUT reference to any
    measurement. Same seed -> same sample, forever."""
    by_state = {}
    for r in rows:
        by_state.setdefault(r.get("state"), []).append(r)
    rng = np.random.default_rng(seed)
    for st in by_state:
        order = rng.permutation(len(by_state[st]))
        by_state[st] = [by_state[st][i] for i in order]
    out, states = [], sorted(by_state)
    while len(out) < n and any(by_state[s] for s in states):
        for s in states:
            if by_state[s] and len(out) < n:
                out.append(by_state[s].pop())
    return out


def run_arm(arm_name, rows, C, g2, g3, dev, manifest):
    def record(row):
        row["arm"] = arm_name
        row["utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        manifest.write(json.dumps(row) + "\n")
        manifest.flush()
        return row

    mine = [r for r in rows if r.get("arm") == arm_name
            and r.get("status") == "OK" and r.get("offline_sha256")]
    if not mine:
        return record({"verdict": "NOT APPLICABLE - NO STAGE 1 OUTPUT",
                       "note": "arm persisted no offline waveform"})

    arm = R1.build_arm(arm_name)
    if arm is None:
        return record({"verdict": "NOT ESTABLISHED - NO ADAPTER HERE",
                       "note": "build_arm() found no frozen adapter"})
    try:
        arm.load(dev)
    except Exception as e:
        return record({"verdict": "NOT ESTABLISHED - ADAPTER FAILED TO LOAD",
                       "note": str(e)})

    allcells = R1.cells(C)
    cellmap = {}
    for c in allcells:
        cellmap[(c["speaker"], c["state"], c["index"], c["rung_s"])] = c

    # ⭐ SPEC S11.2 — THE COLD PROBE, FOR EVERY ARM, AS A RECORDED ROW.
    #
    # Stage 1 decoded 1 736 cells per arm inside one process in frozen corpus
    # order, so the ONLY cell an arm ever produced from a COLD model is
    # cells(C)[0]. Revision 2's bound on the cold-start finding rested on ONE
    # arm, checked by hand, persisted nowhere - and the 216 sampled probes
    # covered that cell 0 times, because it was decoded as warm-up and
    # discarded unhashed.
    #
    # This decodes that exact cell as the FIRST inference after arm.load(), for
    # EVERY arm, hashes it, and compares against the persisted Stage 1 waveform.
    # Arms run sequentially in one process here exactly as they did in Stage 1,
    # so "cold" means the same thing in both: this model newly loaded.
    #
    # It doubles as the warm-up for the sampled probes below - the model is in
    # the state Stage 1 was in for cells 2..1736 once it has run.
    cold = {"cell": None, "verdict": "NOT ESTABLISHED"}
    try:
        c0 = allcells[0]
        k0 = "%s|%s|%s|%s|%s|%s" % (arm_name, c0["set"], c0["speaker"],
                                    c0["state"], c0["index"], c0["rung_s"])
        r0 = next((r for r in mine if r["key"] == k0), None)
        cold["cell"] = k0
        if r0 is None:
            cold["verdict"] = "NOT APPLICABLE - NO STAGE 1 ROW FOR THE FIRST CELL"
        else:
            s0, sr0_ = sf.read(R1.source_path(c0), dtype="float64",
                               always_2d=True)
            s0 = s0.mean(axis=1)
            if c0["rung_s"]:
                s0 = s0[:int(round(c0["rung_s"] * sr0_))]
            sr_c = int(getattr(arm, "sr_in", g2[arm_name]["sr_out"]))
            xc, _ = G4.resample(s0, sr0_, sr_c)
            wc = torch.from_numpy(np.ascontiguousarray(xc)).float()
            # ⛔ THE FIRST INFERENCE THIS MODEL PERFORMS IN THIS PROCESS.
            yc = arm.decode(arm.encode(wc.reshape(1, -1).to(dev))).reshape(1, -1)
            yc = yc.detach().float().cpu().numpy().reshape(-1)
            oldc = np.asarray(sf.read(r0["offline_path"], dtype="float32",
                                      always_2d=False)[0]).reshape(-1)
            cold["stage1_data_sha256"] = data_sha256(oldc)
            cold["cold_redecode_data_sha256"] = data_sha256(yc)
            cold["length_delta"] = int(yc.size - oldc.size)
            n0 = min(oldc.size, yc.size)
            cold["max_abs_diff"] = (
                float(np.abs(oldc[:n0].astype("float64")
                             - yc[:n0].astype("float64")).max()) if n0 else None)
            cold["samples_bit_identical"] = bool(
                cold["stage1_data_sha256"] == cold["cold_redecode_data_sha256"])
            cold["verdict"] = (MATCH if cold["samples_bit_identical"]
                               else "COLD FIRST CELL DOES NOT REPRODUCE")
    except Exception as e:
        cold["verdict"] = "NOT ESTABLISHED - COLD PROBE RAISED"
        cold["error"] = str(e)

    # ⭐ WARM-UP, AND IT IS PART OF THE EXPERIMENTAL DESIGN, NOT A CONVENIENCE.
    # Stage 1 decoded 1 736 cells per arm inside ONE process, in frozen corpus
    # order, so every cell except the FIRST was produced by a WARM model. A
    # probe that decodes cold is therefore not reproducing the condition under
    # test. MEASURED on fish_modified_dac: decoding cell Speaker_03/Angry/909 as the
    # first inference in a fresh process differs from the persisted Stage 1
    # waveform by max|d| = 4.82e-02, and every inference after it is
    # BIT-IDENTICAL - reproducibly, five times in a row. The same arm's actual
    # Stage 1 first cell (Speaker_01/Neutral/902) reproduces cold AND warm, so the
    # effect is input-shape dependent, not universal. This decodes Stage 1's
    # own first cell once and discards it, putting the model in the state
    # Stage 1 was in for cells 2..1736.
    warm = None
    try:
        c0 = allcells[0]
        s0, r0 = sf.read(R1.source_path(c0), dtype="float64", always_2d=True)
        s0 = s0.mean(axis=1)
        if c0["rung_s"]:
            s0 = s0[:int(round(c0["rung_s"] * r0))]
        sr_w = int(getattr(arm, "sr_in", g2[arm_name]["sr_out"]))
        xw, _ = G4.resample(s0, r0, sr_w)
        ww = torch.from_numpy(np.ascontiguousarray(xw)).float().reshape(1, -1)
        arm.decode(arm.encode(ww.to(dev)))
        warm = "%s|%s|%s" % (c0["speaker"], c0["state"], c0["index"])
    except Exception as e:
        warm = "WARM-UP FAILED: %s" % e

    probes, nmatch = [], 0
    for r in sample_cells(mine, N_PER_ARM):
        key = (r["speaker"], r["state"], r["index"], r["rung_s"])
        cell = cellmap.get(key)
        p = {"key": r["key"], "state": r["state"], "speaker": r["speaker"],
             "stage1_sha256": r["offline_sha256"]}
        try:
            src, sr0 = sf.read(R1.source_path(cell), dtype="float64",
                               always_2d=True)
            src = src.mean(axis=1)
            if cell["rung_s"]:
                src = src[:int(round(cell["rung_s"] * sr0))]
            sr_in = int(getattr(arm, "sr_in", g2[arm_name]["sr_out"]))
            x, _ = G4.resample(src, sr0, sr_in)
            wav = torch.from_numpy(np.ascontiguousarray(x)).float()
            wav = wav.reshape(1, -1).to(dev)

            out = arm.decode(arm.encode(wav)).reshape(1, -1)
            y = out.detach().float().cpu().numpy().reshape(-1)
            # (1) FILE INTEGRITY: is the waveform on disk still the one Stage 2
            #     measured? This is what the manifest SHA-256 can prove.
            with open(r["offline_path"], "rb") as fh:
                p["file_sha256_now"] = sha256_bytes(fh.read())
            p["file_unchanged_since_stage1"] = bool(
                p["file_sha256_now"] == p["stage1_sha256"])

            # (2) DECODE REPRODUCIBILITY: are the SAMPLES the frozen path
            #     produces now bit-identical to the samples Stage 1 persisted?
            old, osr = sf.read(r["offline_path"], dtype="float32",
                               always_2d=False)
            old = np.asarray(old).reshape(-1)
            p["stage1_data_sha256"] = data_sha256(old)
            p["redecode_data_sha256"] = data_sha256(y)
            p["sr_equal"] = bool(int(osr) == int(arm.sr_out))
            p["length_delta"] = int(y.size - old.size)
            n = min(old.size, y.size)
            p["max_abs_diff"] = (float(np.abs(old[:n].astype("float64")
                                              - y[:n].astype("float64")).max())
                                 if n else None)
            p["samples_bit_identical"] = bool(
                p["stage1_data_sha256"] == p["redecode_data_sha256"])
            p["match"] = bool(p["samples_bit_identical"]
                              and p["file_unchanged_since_stage1"]
                              and p["sr_equal"])
            nmatch += int(p["match"])
        except Exception as e:
            p["match"] = False
            p["error"] = str(e)
            p["traceback"] = traceback.format_exc()[-800:]
        probes.append(p)

    warm_ok = nmatch == len(probes)
    cold_ok = cold.get("verdict") == MATCH
    return record({
        "verdict": MATCH if (warm_ok and cold_ok) else MISMATCH,
        "warm_verdict": MATCH if warm_ok else MISMATCH,
        "cold_first_cell": cold,
        "n_probes": len(probes), "n_match": nmatch,
        "sample_seed": SAMPLE_SEED,
        "warmup_cell": warm,
        "warmup_rationale": "Stage 1 decoded every cell but the first with a "
                            "WARM model; a cold probe does not reproduce the "
                            "condition under test. See cold_start_finding.",
        "cold_start_finding": "fish_modified_dac's FIRST inference after model "
                              "load can differ (max|d| 4.82e-02 on "
                              "Speaker_03/Angry/909); every inference after it is "
                              "bit-identical. Its actual Stage 1 first cell "
                              "reproduces cold and warm, so at most ONE cell "
                              "per arm per process was ever exposed, and that "
                              "cell was checked directly.",
        "sampling": "deterministic, stratified over states, chosen without "
                    "reference to any measurement",
        "n_file_unchanged": sum(1 for p in probes
                                if p.get("file_unchanged_since_stage1")),
        "n_samples_bit_identical": sum(1 for p in probes
                                       if p.get("samples_bit_identical")),
        "what_this_proves": "TWO things, separately. (1) FILE INTEGRITY: the "
                            "persisted waveform still hashes to the Stage 1 "
                            "manifest value, so the bytes Stage 2 measured are "
                            "unaltered. (2) DECODE REPRODUCIBILITY: re-decoding "
                            "the same corpus cell through the frozen path today "
                            "yields BIT-IDENTICAL samples. The post-hoc "
                            "self-vs-self gate proved neither.",
        "why_not_the_file_hash": "a libsndfile WAV embeds a creation TIMESTAMP "
                                 "in its PEAK chunk (3 bytes at offset 60), so "
                                 "no rewrite ever reproduces the file hash; "
                                 "sample-level hashing is the only valid test",
        "probes": probes})


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--env", required=True)
    ap.add_argument("--arms", default="")
    a = ap.parse_args()

    C, g2, g3 = R1.frozen()
    rows = []
    for f in sorted(os.listdir(os.path.join(HERE, "results"))):
        if f.startswith("gate4_stage1_") and f.endswith(".jsonl"):
            for l in open(os.path.join(HERE, "results", f)):
                try:
                    rows.append(json.loads(l))
                except Exception:
                    pass
    arms = [x for x in a.arms.split(",") if x] or R1.ENV_ARMS.get(a.env, [])
    dev = "cuda" if torch.cuda.is_available() else "cpu"
    out = os.path.join(HERE, "results", "gate4_retro_sha_%s.jsonl" % a.env)

    print("M3 RETROSPECTIVE STAGE 1 SHA-256 CHECK  env=%s device=%s arms=%d "
          "probes/arm=%d" % (a.env, dev, len(arms), N_PER_ARM), flush=True)
    ok = bad = 0
    with open(out, "w") as mf:
        for name in arms:
            t0 = time.time()
            row = run_arm(name, rows, C, g2, g3, dev, mf)
            ok += int(row["verdict"] == MATCH)
            bad += int(row["verdict"] == MISMATCH)
            print("  %-28s %-42s warm %s  cold %s  %.1fs"
                  % (name, row["verdict"],
                     "%d/%d" % (row.get("n_match", 0), row.get("n_probes", 0)),
                     (row.get("cold_first_cell") or {}).get("verdict", "-"),
                     time.time() - t0), flush=True)
    print("\nMATCH=%d  MISMATCH=%d  manifest=%s" % (ok, bad, out), flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())
